/**
 * Render the OpenAPI spec as plain markdown, for the `.md` copies of the API
 * reference pages (and their sections of llms-full.txt).
 *
 * docusaurus-plugin-llms copies each doc's source, and the API reference
 * sources are MDX generated by docusaurus-plugin-openapi-docs: imports and
 * `<RequestSchema {...require("./x.json")}>` components, with every field
 * living in the JSON the component loads. scripts/gen-api-markdown.ts
 * replaces those files after the build with what this module renders.
 */

// The spec is parsed YAML: loosely typed on purpose.
type Node = any;
export type Spec = Node;

export interface OperationRef {
  /** Generated doc id, also the page's file name (`accept-invite`). */
  id: string;
  method: string;
  path: string;
}

const MAX_DEPTH = 5;

/** Follow a local `$ref` (`#/components/...`), returning the target node. */
export function deref(spec: Spec, node: Node): Node {
  let current = node;
  const seen = new Set<string>();
  while (current && typeof current.$ref === "string") {
    const ref: string = current.$ref;
    if (seen.has(ref) || !ref.startsWith("#/")) break;
    seen.add(ref);
    current = ref
      .slice(2)
      .split("/")
      .reduce((acc: Node, key) => acc?.[key.replace(/~1/g, "/").replace(/~0/g, "~")], spec);
  }
  return current;
}

function refName(node: Node): string | undefined {
  return typeof node?.$ref === "string" ? node.$ref.split("/").pop() : undefined;
}

/** One line, safe inside a markdown table cell. */
function cell(text: unknown): string {
  if (text === undefined || text === null) return "";
  return String(text).replace(/\s+/g, " ").trim().replace(/\|/g, "\\|");
}

/** Merge the members of an `allOf` into one object schema. */
function flatten(spec: Spec, schema: Node): Node {
  const s = deref(spec, schema);
  if (!s?.allOf) return s;
  const merged: Node = { ...s, properties: { ...s.properties }, required: [...(s.required ?? [])] };
  delete merged.allOf;
  for (const part of s.allOf) {
    const p = flatten(spec, part);
    if (!p) continue;
    Object.assign(merged.properties, p.properties);
    merged.required.push(...(p.required ?? []));
    merged.type ??= p.type;
    merged.description ??= p.description;
    merged.enum ??= p.enum;
    merged.format ??= p.format;
    merged.items ??= p.items;
  }
  if (Object.keys(merged.properties).length === 0) delete merged.properties;
  return merged;
}

/** Short type label: `string (date-time)`, `array of Check`, `one of A, B`. */
export function typeLabel(spec: Spec, schema: Node): string {
  if (!schema) return "";
  const name = refName(schema);
  const s = flatten(spec, schema);
  if (!s) return name ?? "";
  let label: string;
  const variants = s.oneOf ?? s.anyOf;
  if (variants) {
    label = `one of ${variants.map((v: Node) => typeLabel(spec, v)).join(", ")}`;
  } else if (s.type === "array") {
    label = `array of ${typeLabel(spec, s.items) || "any"}`;
  } else if (s.type === "object" || s.properties || s.additionalProperties) {
    if (!s.properties && s.additionalProperties && s.additionalProperties !== true) {
      label = `map of ${typeLabel(spec, s.additionalProperties)}`;
    } else {
      label = name ?? "object";
    }
  } else {
    label = s.type ?? name ?? "any";
    if (s.format) label += ` (${s.format})`;
  }
  if (s.nullable) label += ", nullable";
  return label;
}

function details(s: Node): string {
  const parts: string[] = [];
  if (s?.description) {
    const text = cell(s.description);
    parts.push(/[.!?:)]$/.test(text) ? text : `${text}.`);
  }
  if (s?.enum) {
    parts.push(`One of: ${s.enum.map((v: unknown) => (v === "" ? '`""`' : `\`${v}\``)).join(", ")}.`);
  }
  if (s?.default !== undefined) parts.push(`Default: \`${JSON.stringify(s.default)}\`.`);
  if (s?.example !== undefined) parts.push(`Example: \`${cell(JSON.stringify(s.example))}\`.`);
  if (s?.deprecated) parts.push("Deprecated.");
  return parts.join(" ");
}

interface Row {
  name: string;
  type: string;
  required: boolean;
  description: string;
}

/** The object to list fields of, if this schema (or the array's items) has any. */
function fieldsOf(spec: Spec, schema: Node): { obj: Node; suffix: string } | undefined {
  const s = flatten(spec, schema);
  if (s?.properties) return { obj: s, suffix: "." };
  if (s?.type === "array") {
    const items = flatten(spec, s.items);
    if (items?.properties) return { obj: items, suffix: "[]." };
  }
  return undefined;
}

function collectRows(
  spec: Spec,
  obj: Node,
  prefix: string,
  depth: number,
  seen: Set<string>,
  rows: Row[],
): void {
  const required = new Set<string>(obj.required ?? []);
  for (const [key, prop] of Object.entries<Node>(obj.properties ?? {})) {
    // A property's own description overrides its $ref target's.
    const s = { ...flatten(spec, prop), ...(prop?.description ? { description: prop.description } : {}) };
    rows.push({
      name: prefix + key,
      type: typeLabel(spec, prop),
      required: required.has(key),
      description: details(s),
    });
    const ref = refName(prop) ?? refName(deref(spec, prop)?.items) ?? refName(prop?.items);
    const nested = fieldsOf(spec, prop);
    if (!nested || depth >= MAX_DEPTH || (ref && seen.has(ref))) continue;
    const next = new Set(seen);
    if (ref) next.add(ref);
    collectRows(spec, nested.obj, prefix + key + nested.suffix, depth + 1, next, rows);
  }
}

/** Markdown for a body schema: a field table, or its type when it has no fields. */
export function renderSchema(spec: Spec, schema: Node): string {
  const top = fieldsOf(spec, schema);
  if (!top) {
    const s = flatten(spec, schema);
    const variants = s?.oneOf ?? s?.anyOf;
    if (variants) {
      return variants
        .map((v: Node) => `Variant \`${typeLabel(spec, v)}\`:\n\n${renderSchema(spec, v)}`)
        .join("\n\n");
    }
    const extra = details(s);
    return `Type: \`${typeLabel(spec, schema)}\`${extra ? `. ${extra}` : ""}`;
  }
  const rows: Row[] = [];
  const ref = refName(schema) ?? refName(deref(spec, schema)?.items);
  collectRows(spec, top.obj, top.suffix === "[]." ? "[]." : "", 1, new Set(ref ? [ref] : []), rows);
  const lines = ["| Field | Type | Required | Description |", "| --- | --- | --- | --- |"];
  for (const r of rows) {
    lines.push(`| \`${r.name}\` | ${cell(r.type)} | ${r.required ? "yes" : "no"} | ${r.description} |`);
  }
  return lines.join("\n");
}

function renderAuth(spec: Spec, op: Node): string {
  const security: Node[] | undefined = op.security ?? spec.security;
  if (!security || security.length === 0) return "None, public endpoint.";
  const schemes = security.map((req) => Object.keys(req));
  const optional = schemes.some((names) => names.length === 0);
  const labels = schemes
    .filter((names) => names.length > 0)
    .map((names) =>
      names
        .map((name) => {
          const scheme = spec.components?.securitySchemes?.[name];
          if (scheme?.type === "http" && scheme.scheme === "bearer") {
            return "`Authorization: Bearer <token>`";
          }
          return `\`${name}\``;
        })
        .join(" + "),
    );
  if (labels.length === 0) return "None, public endpoint.";
  return optional ? `Optional: ${labels.join(" or ")}.` : `${labels.join(" or ")}.`;
}

function renderBody(spec: Spec, content: Node): string {
  const out: string[] = [];
  for (const [type, media] of Object.entries<Node>(content ?? {})) {
    out.push(`Content type: \`${type}\``);
    if (media?.schema) out.push(renderSchema(spec, media.schema));
    if (media?.example !== undefined) {
      out.push(`Example:\n\n\`\`\`json\n${JSON.stringify(media.example, null, 2)}\n\`\`\``);
    }
  }
  return out.join("\n\n");
}

export function renderOperation(spec: Spec, method: string, path: string): string {
  const pathItem = spec.paths?.[path];
  const op = pathItem?.[method];
  if (!op) throw new Error(`operation ${method.toUpperCase()} ${path} not in the spec`);

  const out: string[] = [`# ${op.summary ?? op.operationId}`, `\`${method.toUpperCase()} ${path}\``];
  if (op.deprecated) out.push("**Deprecated.**");
  if (op.description) out.push(op.description.trim());
  out.push(`## Authentication\n\n${renderAuth(spec, op)}`);

  const params = [...(pathItem.parameters ?? []), ...(op.parameters ?? [])].map((p) => deref(spec, p));
  if (params.length > 0) {
    const lines = ["| Name | In | Type | Required | Description |", "| --- | --- | --- | --- | --- |"];
    for (const p of params) {
      const s = flatten(spec, p.schema);
      const desc = [cell(p.description), details({ ...s, description: undefined })].filter(Boolean).join(" ");
      lines.push(
        `| \`${p.name}\` | ${p.in} | ${cell(typeLabel(spec, p.schema))} | ${p.required ? "yes" : "no"} | ${desc} |`,
      );
    }
    out.push(`## Parameters\n\n${lines.join("\n")}`);
  }

  if (op.requestBody) {
    const body = deref(spec, op.requestBody);
    const head = [body.required ? "Required." : "Optional.", body.description?.trim()].filter(Boolean).join(" ");
    out.push(`## Request body\n\n${head}\n\n${renderBody(spec, body.content)}`);
  }

  const responses = Object.entries<Node>(op.responses ?? {});
  if (responses.length > 0) {
    const parts = responses.map(([code, raw]) => {
      const res = deref(spec, raw);
      const section = [`### ${code}`];
      if (res?.description) section.push(res.description.trim());
      // Error bodies are all the same shape: name it instead of repeating it.
      const errorName = Object.values<Node>(res?.content ?? {})
        .map((m) => refName(m?.schema))
        .find((n) => n === "Error");
      if (errorName) section.push("Body: an `Error` object (`title`, `code`, `detail`).");
      else if (res?.content) section.push(renderBody(spec, res.content));
      return section.join("\n\n");
    });
    out.push(`## Responses\n\n${parts.join("\n\n")}`);
  }

  return `${out.join("\n\n")}\n`;
}

export function renderTag(
  spec: Spec,
  tag: string,
  operations: (OperationRef & { title: string })[],
  linkBase: string,
): string {
  const description = spec.tags?.find((t: Node) => t.name === tag)?.description;
  const out = [`# ${tag}`];
  if (description) out.push(description.trim());
  out.push(
    operations.map((o) => `- [${o.title}](${linkBase}${o.id}.md): \`${o.method.toUpperCase()} ${o.path}\``).join("\n"),
  );
  return `${out.join("\n\n")}\n`;
}

export function renderInfo(spec: Spec, tags: { id: string; name: string }[], linkBase: string): string {
  const info = spec.info ?? {};
  const out = [`# ${info.title ?? "API"}`];
  if (info.description) out.push(info.description.trim());
  if (info.version) out.push(`Version: \`${info.version}\``);
  if (spec.servers?.length) {
    out.push(
      `## Servers\n\n${spec.servers.map((s: Node) => `- \`${s.url}\`${s.description ? `: ${s.description}` : ""}`).join("\n")}`,
    );
  }
  const schemes = Object.entries<Node>(spec.components?.securitySchemes ?? {});
  if (schemes.length > 0) {
    const lines = schemes.map(([name, s]) =>
      s.type === "http" && s.scheme === "bearer"
        ? `- \`${name}\`: send \`Authorization: Bearer <token>\`${s.bearerFormat ? ` (${s.bearerFormat})` : ""}.`
        : `- \`${name}\`: ${s.type}.`,
    );
    out.push(`## Authentication\n\n${lines.join("\n")}`);
  }
  if (tags.length > 0) {
    out.push(`## Sections\n\n${tags.map((t) => `- [${t.name}](${linkBase}${t.id}.md)`).join("\n")}`);
  }
  if (info.license?.name) {
    out.push(`## License\n\n${info.license.url ? `[${info.license.name}](${info.license.url})` : info.license.name}`);
  }
  return `${out.join("\n\n")}\n`;
}
